    def wrapper(*args, **kwargs):
        return func(*args, **kwargs).upper()
    return wrapper

def double_result(func):
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs) * 2
    return wrapper

def repeat(times):
    def decorator(func):
        def wrapper(*args, **kwargs):
            return [func(*args, **kwargs) for _ in range(times)]
        return wrapper
    return decorator

def evens_up_to(n):
    value = 0
    while value <= n:
        yield value
        value += 2

