class ResourcePool:
    def __init__(self, size):
        self.size = size
        self.in_use = 0
        self.events = []

    def __enter__(self):
        self.in_use += 1
        self.events.append('acquired')
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.in_use -= 1
        self.events.append('released')
        return False

    def track(self, func):
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            self.events.append('called:' + func.__name__)
            return result
        return wrapper

    def usage_report(self):
        report = {}
        for event in self.events:
            key = event.split(':')[0]
            report[key] = report.get(key, 0) + 1
        return report
